{"id":"gen-1792764096-hmVfwxmEbsCUDHMcq3Hh","object":"chat.completion","created":1792764096,"model":"openai/gpt-6-luna","provider":"OpenAI","system_fingerprint":null,"service_tier":"default","choices":[{"index":0,"logprobs":null,"finish_reason":"stop","native_finish_reason":"completed","message":{"role":"assistant","content":"{
